mapper.select:
SELECT code_value AS code, code_description_zh_tw AS description, code_description_en AS descriptionEn, classification_code AS classificationCode, classification_description_zh_tw AS classificationDescription, breakdown_code AS breakdownCode, breakdown_description_zh_tw AS breakdownDescription, nature_of_work_zh_tw AS natureOfWork, source_version AS sourceVersion FROM new_contract.code_definition WHERE code_group = #{codeGroup} AND code_field = #{codeField} AND active_flag = 'Y' AND effective_from <= CURRENT_DATE AND (effective_to IS NULL OR effective_to >= CURRENT_DATE)
AND (code_value LIKE CONCAT(#{query}, '%') OR code_description_zh_tw LIKE CONCAT('%', #{query}, '%'))
ORDER BY display_order, code_value LIMIT #{pageSize} OFFSET #{offset}

SELECT EXISTS (
  SELECT 1
    FROM new_contract.code_definition
   WHERE code_group = #{codeGroup}
     AND code_field = #{codeField}
     AND code_value = #{code}
     AND active_flag = 'Y'
     AND effective_from <= CURRENT_DATE
     AND (effective_to IS NULL OR effective_to >= CURRENT_DATE)
)
